class Solution:

	def antiDiagonalPattern(self, m):
		e = []
		for i in range(len(m[0])):
			a = i
			for j in range(len(m)):
				if a >= 0:
					e += [m[j][a]]
				a -= 1
		for i in range(len(m[0])):
			b = len(m[0]) - 1
			for j in range(i + 1, len(m)):
				if b >= 0:
					e += [m[j][b]]
				b -= 1
		return e
